pub fn bad(e: usize) -> bool {
    return (e != 0);
}

pub fn block_end(src: &[u8], o: usize) -> usize {
    let mut depth: usize = 0;
    let mut q: usize = o;
    while (q < src.len()) {
        let e: usize = tok_end(src, q);
        if ((e == (q + 1)) && is_open(src[(q) as usize])) {
            depth = (depth + 1);
        }
        if ((e == (q + 1)) && is_close(src[(q) as usize])) {
            if (depth <= 1) {
                return e;
            }
            depth = (depth - 1);
        }
        q = skip_ws(src, e);
    }
    return src.len();
}

pub fn count_fns(src: &[u8], lo: usize, hi: usize) -> usize {
    let mut n: usize = 0;
    let mut q: usize = lo;
    while (q < hi) {
        let e: usize = tok_end(src, q);
        if word_is(src, q, e, b"fn") {
            let k: usize = skip_ws(src, e);
            if ((k < src.len()) && is_alpha(src[(k) as usize])) {
                n = (n + 1);
            }
        }
        q = skip_ws(src, e);
    }
    return n;
}

pub fn find_at(src: &[u8], from: usize, c: u8) -> usize {
    let mut depth: usize = 0;
    let mut q: usize = from;
    while (q < src.len()) {
        let e: usize = tok_end(src, q);
        if (e == (q + 1)) {
            if ((src[(q) as usize] == c) && (depth == 0)) {
                return q;
            }
            if is_open(src[(q) as usize]) {
                depth = (depth + 1);
            }
            if is_close(src[(q) as usize]) {
                if (depth == 0) {
                    return src.len();
                }
                depth = (depth - 1);
            }
        }
        q = skip_ws(src, e);
    }
    return src.len();
}

pub fn head(src: &[u8], p: usize) -> u8 {
    if (p >= src.len()) {
        return 0;
    }
    return src[(p) as usize];
}

pub fn insert(st: &mut [usize], out: &mut [u8], pos: usize, s: &[u8]) -> () {
    if open_gap(st, out, pos, s.len()) {
        let mut k: usize = 0;
        while (k < s.len()) {
            out[((pos + k)) as usize] = s[(k) as usize];
            k = (k + 1);
        }
    }
}

pub fn is_alpha(c: u8) -> bool {
    return ((((c >= B_LOWER_A) && (c <= B_LOWER_Z)) || is_upper(c)) || (c == B_UNDERSCORE));
}

pub fn is_close(c: u8) -> bool {
    return (((c == B_RPAREN) || (c == B_RBRACKET)) || (c == B_RBRACE));
}

pub fn is_digit(c: u8) -> bool {
    return ((c >= B_ZERO) && (c <= B_NINE));
}

pub fn is_open(c: u8) -> bool {
    return (((c == B_LPAREN) || (c == B_LBRACKET)) || (c == B_LBRACE));
}

pub fn is_space(c: u8) -> bool {
    return ((((c == B_SPACE) || (c == B_TAB)) || (c == B_NL)) || (c == B_CR));
}

pub fn is_upper(c: u8) -> bool {
    return ((c >= B_UPPER_A) && (c <= B_UPPER_Z));
}

pub fn is_word(c: u8) -> bool {
    return (is_alpha(c) || is_digit(c));
}

pub fn keep_bare(child: usize, parent: usize, left: bool) -> bool {
    if ((child == L_ATOM) || (child == L_UNARY)) {
        return true;
    }
    if (child == parent) {
        return ((left && (parent != L_CMP)) && (parent != L_AS));
    }
    if ((((child == L_BOR) || (child == L_XOR)) || (child == L_BAND)) || (child == L_AS)) {
        return false;
    }
    if (((parent == L_BOR) || (parent == L_XOR)) || (parent == L_BAND)) {
        return false;
    }
    return (child > parent);
}

pub fn line_at(src: &[u8], st: &mut [usize], pos: usize) -> usize {
    let mut i: usize = 0;
    let mut n: usize = 0;
    if (st[(LNPOS) as usize] <= pos) {
        i = st[(LNPOS) as usize];
        n = st[(LNNL) as usize];
    }
    let mut end: usize = pos;
    if (end > src.len()) {
        end = src.len();
    }
    while (i < end) {
        if (src[(i) as usize] == B_NL) {
            n = (n + 1);
        }
        i = (i + 1);
    }
    st[(LNPOS) as usize] = end;
    st[(LNNL) as usize] = n;
    return (n + 1);
}

pub fn newline(st: &mut [usize], out: &mut [u8]) -> () {
    put(st, out, B_NL);
    let mut k: usize = 0;
    while (k < st[(IND) as usize]) {
        puts(st, out, b"    ");
        k = (k + 1);
    }
}

pub fn num_end(src: &[u8], p: usize) -> usize {
    let mut e: usize = (p + 1);
    if (((src[(p) as usize] == B_ZERO) && (e < src.len())) && (((src[(e) as usize] == B_LOWER_X) || (src[(e) as usize] == B_LOWER_O)) || (src[(e) as usize] == B_LOWER_B))) {
        e = (e + 1);
        while ((e < src.len()) && is_word(src[(e) as usize])) {
            e = (e + 1);
        }
        return e;
    }
    while ((e < src.len()) && (is_digit(src[(e) as usize]) || (src[(e) as usize] == B_UNDERSCORE))) {
        e = (e + 1);
    }
    if ((((e + 1) < src.len()) && (src[(e) as usize] == B_DOT)) && is_digit(src[((e + 1)) as usize])) {
        e = (e + 1);
        while ((e < src.len()) && (is_digit(src[(e) as usize]) || (src[(e) as usize] == B_UNDERSCORE))) {
            e = (e + 1);
        }
    }
    if ((e < src.len()) && ((src[(e) as usize] == B_LOWER_E) || (src[(e) as usize] == B_UPPER_E))) {
        let mut x: usize = (e + 1);
        if ((x < src.len()) && ((src[(x) as usize] == B_PLUS) || (src[(x) as usize] == B_MINUS))) {
            x = (x + 1);
        }
        if ((x < src.len()) && is_digit(src[(x) as usize])) {
            e = x;
            while ((e < src.len()) && (is_digit(src[(e) as usize]) || (src[(e) as usize] == B_UNDERSCORE))) {
                e = (e + 1);
            }
        }
    }
    while ((e < src.len()) && is_word(src[(e) as usize])) {
        e = (e + 1);
    }
    return e;
}

pub fn op2(src: &[u8], p: usize) -> bool {
    let a: u8 = src[(p) as usize];
    let b: u8 = src[((p + 1)) as usize];
    if (b == B_EQ) {
        return ((((((((((((a == B_EQ) || (a == B_BANG)) || (a == B_LT)) || (a == B_GT)) || (a == B_PLUS)) || (a == B_MINUS)) || (a == B_STAR)) || (a == B_SLASH)) || (a == B_PCT)) || (a == B_CARET)) || (a == B_AMP)) || (a == B_PIPE));
    }
    if ((a == B_COLON) && (b == B_COLON)) {
        return true;
    }
    if (((a == B_MINUS) || (a == B_EQ)) && (b == B_GT)) {
        return true;
    }
    if ((a == b) && (((((a == B_AMP) || (a == B_PIPE)) || (a == B_LT)) || (a == B_GT)) || (a == B_DOT))) {
        return true;
    }
    return false;
}

pub fn op3(src: &[u8], p: usize) -> bool {
    let a: u8 = src[(p) as usize];
    let b: u8 = src[((p + 1)) as usize];
    let c: u8 = src[((p + 2)) as usize];
    if ((((a == B_LT) || (a == B_GT)) && (b == a)) && (c == B_EQ)) {
        return true;
    }
    return (((a == B_DOT) && (b == B_DOT)) && ((c == B_EQ) || (c == B_DOT)));
}

pub fn open_gap(st: &mut [usize], out: &mut [u8], pos: usize, n: usize) -> bool {
    let w: usize = st[(W) as usize];
    let grown: usize = (w + n);
    st[(W) as usize] = grown;
    if (grown > out.len()) {
        return false;
    }
    let mut i: usize = w;
    while (i > pos) {
        i = (i - 1);
        out[((i + n)) as usize] = out[(i) as usize];
    }
    return true;
}

pub fn out_is(w: usize, out: &[u8], from: usize, s: &[u8]) -> bool {
    if (((w < from) || ((w - from) != s.len())) || (w > out.len())) {
        return false;
    }
    let mut k: usize = 0;
    while (k < s.len()) {
        if (out[((from + k)) as usize] != s[(k) as usize]) {
            return false;
        }
        k = (k + 1);
    }
    return true;
}

pub fn put(st: &mut [usize], out: &mut [u8], c: u8) -> () {
    let w: usize = st[(W) as usize];
    if (w < out.len()) {
        out[(w) as usize] = c;
    }
    st[(W) as usize] = (w + 1);
}

pub fn put_ident(src: &[u8], st: &mut [usize], out: &mut [u8], a: usize, b: usize) -> () {
    put_src(src, st, out, a, b);
    if reserved(src, a, b) {
        puts(st, out, b"_");
    }
}

pub fn put_num(st: &mut [usize], out: &mut [u8], v: usize) -> () {
    if (v >= 10) {
        put_num(st, out, (v / 10));
    }
    put(st, out, (B_ZERO + ((v % 10) as u8)));
}

pub fn put_src(src: &[u8], st: &mut [usize], out: &mut [u8], a: usize, b: usize) -> () {
    let mut i: usize = a;
    while ((i < b) && (i < src.len())) {
        put(st, out, src[(i) as usize]);
        i = (i + 1);
    }
}

pub fn put_text(src: &[u8], st: &mut [usize], out: &mut [u8], a: usize, b: usize, max: usize) -> () {
    let mut i: usize = a;
    while (((i < b) && (i < src.len())) && (i < (a + max))) {
        let c: u8 = src[(i) as usize];
        if ((c >= B_SPACE) && (c < B_DEL)) {
            put(st, out, c);
        } else {
            if ((c < 128) || (c >= 192)) {
                put(st, out, 63);
            }
        }
        i = (i + 1);
    }
}

pub fn puts(st: &mut [usize], out: &mut [u8], s: &[u8]) -> () {
    let mut i: usize = 0;
    while (i < s.len()) {
        put(st, out, s[(i) as usize]);
        i = (i + 1);
    }
}

pub fn quoted_end(src: &[u8], q: usize) -> usize {
    let quote: u8 = src[(q) as usize];
    let mut p: usize = (q + 1);
    while (p < src.len()) {
        if (src[(p) as usize] == B_BACKSLASH) {
            p = (p + 2);
        } else {
            if (src[(p) as usize] == quote) {
                return (p + 1);
            } else {
                p = (p + 1);
            }
        }
    }
    return src.len();
}

pub fn raw_end(src: &[u8], r: usize) -> usize {
    let mut p: usize = (r + 1);
    let mut hashes: usize = 0;
    while ((p < src.len()) && (src[(p) as usize] == B_HASH)) {
        hashes = (hashes + 1);
        p = (p + 1);
    }
    if ((p >= src.len()) || (src[(p) as usize] != B_QUOTE)) {
        return (r + 1);
    }
    p += 1;
    while (p < src.len()) {
        if (src[(p) as usize] == B_QUOTE) {
            let mut k: usize = 0;
            while (((k < hashes) && (((p + 1) + k) < src.len())) && (src[(((p + 1) + k)) as usize] == B_HASH)) {
                k = (k + 1);
            }
            if (k == hashes) {
                return ((p + 1) + hashes);
            }
        }
        p = (p + 1);
    }
    return src.len();
}

pub fn refuse(st: &mut [usize], code: usize, pos: usize, lo: usize, hi: usize) -> () {
    if (st[(ERR) as usize] == 0) {
        st[(ERR) as usize] = code;
        st[(AT) as usize] = pos;
        st[(NLO) as usize] = lo;
        st[(NHI) as usize] = hi;
    }
}

pub fn reserved(src: &[u8], a: usize, b: usize) -> bool {
    return ((((((((((((((((((((((((((word_is(src, a, b, b"and") || word_is(src, a, b, b"or")) || word_is(src, a, b, b"test")) || word_is(src, a, b, b"var")) || word_is(src, a, b, b"error")) || word_is(src, a, b, b"null")) || word_is(src, a, b, b"undefined")) || word_is(src, a, b, b"switch")) || word_is(src, a, b, b"orelse")) || word_is(src, a, b, b"try")) || word_is(src, a, b, b"defer")) || word_is(src, a, b, b"comptime")) || word_is(src, a, b, b"module")) || word_is(src, a, b, b"invariant")) || word_is(src, a, b, b"bench")) || word_is(src, a, b, b"catch")) || word_is(src, a, b, b"unreachable")) || word_is(src, a, b, b"anytype")) || word_is(src, a, b, b"opaque")) || word_is(src, a, b, b"packed")) || word_is(src, a, b, b"export")) || word_is(src, a, b, b"inline")) || word_is(src, a, b, b"align")) || word_is(src, a, b, b"noreturn")) || word_is(src, a, b, b"errdefer")) || word_is(src, a, b, b"spec")) || word_is(src, a, b, b"void"));
}

pub fn reverse(out: &mut [u8], a: usize, b: usize) -> () {
    let mut i: usize = a;
    let mut j: usize = b;
    while (j > (i + 1)) {
        j = (j - 1);
        let t: u8 = out[(i) as usize];
        out[(i) as usize] = out[(j) as usize];
        out[(j) as usize] = t;
        i = (i + 1);
    }
}

pub fn same_at(src: &[u8], q: usize, e: usize, a: usize) -> bool {
    let mut k: usize = 0;
    while ((q + k) < e) {
        if (((a + k) >= src.len()) || (src[((q + k)) as usize] != src[((a + k)) as usize])) {
            return false;
        }
        k = (k + 1);
    }
    return true;
}

pub fn same_text(src: &[u8], a: usize, b: usize, c: usize, d: usize) -> bool {
    if (((b < a) || (d < c)) || ((b - a) != (d - c))) {
        return false;
    }
    return same_at(src, a, b, c);
}

pub fn skip_ws(src: &[u8], from: usize) -> usize {
    let mut p: usize = from;
    while (p < src.len()) {
        let c: u8 = src[(p) as usize];
        if is_space(c) {
            p = (p + 1);
        } else {
            if (((c == B_SLASH) && ((p + 1) < src.len())) && (src[((p + 1)) as usize] == B_SLASH)) {
                while ((p < src.len()) && (src[(p) as usize] != B_NL)) {
                    p = (p + 1);
                }
            } else {
                if (((c == B_SLASH) && ((p + 1) < src.len())) && (src[((p + 1)) as usize] == B_STAR)) {
                    let mut depth: usize = 1;
                    p = (p + 2);
                    while ((p < src.len()) && (depth > 0)) {
                        if (((src[(p) as usize] == B_STAR) && ((p + 1) < src.len())) && (src[((p + 1)) as usize] == B_SLASH)) {
                            depth = (depth - 1);
                            p = (p + 2);
                        } else {
                            if (((src[(p) as usize] == B_SLASH) && ((p + 1) < src.len())) && (src[((p + 1)) as usize] == B_STAR)) {
                                depth = (depth + 1);
                                p = (p + 2);
                            } else {
                                p = (p + 1);
                            }
                        }
                    }
                } else {
                    return p;
                }
            }
        }
    }
    return p;
}

pub fn tok_end(src: &[u8], p: usize) -> usize {
    if (p >= src.len()) {
        return p;
    }
    let c: u8 = src[(p) as usize];
    if (((c == B_LOWER_B) && ((p + 1) < src.len())) && ((src[((p + 1)) as usize] == B_QUOTE) || (src[((p + 1)) as usize] == B_APOS))) {
        return quoted_end(src, (p + 1));
    }
    if (((c == B_LOWER_R) && ((p + 1) < src.len())) && ((src[((p + 1)) as usize] == B_QUOTE) || (src[((p + 1)) as usize] == B_HASH))) {
        return raw_end(src, p);
    }
    if is_alpha(c) {
        let mut e: usize = (p + 1);
        while ((e < src.len()) && is_word(src[(e) as usize])) {
            e = (e + 1);
        }
        return e;
    }
    if is_digit(c) {
        return num_end(src, p);
    }
    if (c == B_QUOTE) {
        return quoted_end(src, p);
    }
    if (c == B_APOS) {
        if (((p + 1) < src.len()) && (src[((p + 1)) as usize] == B_BACKSLASH)) {
            return quoted_end(src, p);
        }
        if (((p + 2) < src.len()) && (src[((p + 2)) as usize] == B_APOS)) {
            return (p + 3);
        }
        let mut e: usize = (p + 1);
        while ((e < src.len()) && is_word(src[(e) as usize])) {
            e = (e + 1);
        }
        return e;
    }
    if (((p + 2) < src.len()) && op3(src, p)) {
        return (p + 3);
    }
    if (((p + 1) < src.len()) && op2(src, p)) {
        return (p + 2);
    }
    return (p + 1);
}

pub fn word_is(src: &[u8], a: usize, b: usize, s: &[u8]) -> bool {
    if ((b < a) || ((b - a) != s.len())) {
        return false;
    }
    let mut k: usize = 0;
    while (k < s.len()) {
        if (src[((a + k)) as usize] != s[(k) as usize]) {
            return false;
        }
        k = (k + 1);
    }
    return true;
}

pub fn wrap(st: &mut [usize], out: &mut [u8], from: usize) -> () {
    insert(st, out, from, b"(");
    puts(st, out, b")");
}

